content.text:
sanitize_log_value(getattr(record, attribute_name)),
                )

        return record.levelno >= logging.NOTSET


def _attach_filter_once(
    logger: logging.Logger, filter_instance: logging.Filter
) -> None:
    """Attach a filter only if an instance of the same type is not already present."""
    if any(
        isinstance(existing_filter, type(filter_instance))
        for existing_filter in logger.filters
    ):
        return
    logger.addFilter(filter_instance)


def configure_external_logger_privacy(logger_name: str) -> None:
    """Attach privacy redaction to a non-application logger by name."""
    _attach_filter_once(logging.getLogger(logger_name), SensitiveDataFilter())


def get_bizlog_logger(
    name: str | None = None, service_name: str | None = None
) -> logging.Logger:
    """Get a bizlog logger or a stdlib fallback logger.

    Args:
        name: Module/file logger name.
        service_name: Service logger name used for INFO and higher logs.
            Kept for compatibility; INFO and higher logs are standardized to
            ``dokumentenpruefung``.

    Returns:
        Logger-like object compatible with ``logging.Logger``.
    """
    logger = _bizlog_get_logger(name)
    if hasattr(logger, "setLevel"):
        logger.setLevel(logging.INFO)

    _ = service_name  # service name is standardized at wrapper level
    resolved_service_name = _STANDARD_SERVICE_NAME

    if name and resolved_service_name:
        level_filter = LevelBasedNameFilter(
            file_name=name, service_name=resolved_service_name
        )
        base_logger = getattr(logger, "_logger", None)
        if isinstance(base_logger, logging.Logger):
            _attach_filter_once(base_logger, level_filter)
